"""Schema-driven validation.

Schemas are plain dicts::

    {'type': 'object', 'fields': {
        'name': {'type': 'string', 'min_len': 1},
        'age':  {'type': 'int', 'min': 0, 'max': 150},
        'tags': {'type': 'list', 'item': {'type': 'string',
                                          'pattern': '^[a-z]+$'}},
        'address': {'type': 'object', 'optional': True, 'fields': {
            'zip': {'type': 'string', 'pattern': r'^\d{5}$'}}}}}

``validate(schema, value)`` returns ALL errors as ``(path, message)`` pairs,
where ``path`` composes like ``address.zip`` or ``tags[3]`` (``""`` denotes
the root). An empty list means valid. Validation never stops at the first
error within a scope.

``serialize(schema, value)`` returns a canonical dict containing exactly the
declared fields (recursively); any validation failure -- including unknown
fields, reported at their own path -- raises :class:`SchemaValidationError`.
"""

import re

__all__ = ["validate", "serialize", "SchemaValidationError"]


class SchemaValidationError(ValueError):
    """Raised by :func:`serialize` when the value does not match the schema."""

    def __init__(self, errors):
        self.errors = list(errors)
        summary = "; ".join(f"{p or '<root>'}: {m}" for p, m in self.errors)
        super().__init__(f"{len(self.errors)} validation error(s): {summary}")


def _join(path, key):
    return f"{path}.{key}" if path else key


def _index(path, i):
    return f"{path}[{i}]"


def _is_int(value):
    # bool is a subclass of int; reject it explicitly.
    return isinstance(value, int) and not isinstance(value, bool)


def _collect_errors(schema, value, path, errors):
    """Accumulate every violation of ``schema`` by ``value`` into ``errors``."""
    stype = schema.get("type")

    if stype == "object":
        _collect_object(schema, value, path, errors)
    elif stype == "list":
        _collect_list(schema, value, path, errors)
    elif stype == "string":
        _collect_string(schema, value, path, errors)
    elif stype == "int":
        _collect_int(schema, value, path, errors)
    else:
        raise ValueError(f"unknown schema type: {stype!r} at path {path!r}")


def _collect_object(schema, value, path, errors):
    if not isinstance(value, dict):
        errors.append((path, f"expected object, got {type(value).__name__}"))
        return

    fields = schema.get("fields", {})
    where = lambda k: _join(path, k)

    # Known fields: recurse (present) or demand presence (required).
    for key, subschema in fields.items():
        if key in value:
            _collect_errors(subschema, value[key], where(key), errors)
        elif not subschema.get("optional", False):
            errors.append((where(key), "missing required field"))

    # Unknown fields are rejected at their own path.
    for key in value:
        if key not in fields:
            errors.append((where(key), "unknown field"))


def _collect_list(schema, value, path, errors):
    if not isinstance(value, list):
        errors.append((path, f"expected list, got {type(value).__name__}"))
        return

    item_schema = schema.get("item")
    if item_schema is None:
        return
    for i, item in enumerate(value):
        _collect_errors(item_schema, item, _index(path, i), errors)


def _collect_string(schema, value, path, errors):
    if not isinstance(value, str):
        errors.append((path, f"expected string, got {type(value).__name__}"))
        return  # constraints are meaningless on non-strings; report type only

    min_len = schema.get("min_len")
    if min_len is not None and len(value) < min_len:
        errors.append(
            (path, f"length {len(value)} is below minimum {min_len}")
        )

    max_len = schema.get("max_len")
    if max_len is not None and len(value) > max_len:
        errors.append(
            (path, f"length {len(value)} exceeds maximum {max_len}")
        )

    pattern = schema.get("pattern")
    if pattern is not None and re.match(pattern, value) is None:
        errors.append((path, f"does not match pattern {pattern!r}"))


def _collect_int(schema, value, path, errors):
    if not _is_int(value):
        errors.append((path, f"expected int, got {type(value).__name__}"))
        return  # constraints are meaningless on non-ints; report type only

    minimum = schema.get("min")
    if minimum is not None and value < minimum:
        errors.append((path, f"{value} is below minimum {minimum}"))

    maximum = schema.get("max")
    if maximum is not None and value > maximum:
        errors.append((path, f"{value} exceeds maximum {maximum}"))


def validate(schema, value):
    """Validate ``value`` against ``schema``.

    Returns a list of all ``(path, message)`` errors (empty means valid).
    Paths compose: ``address.zip``, ``tags[3]``, ``""`` at the root.
    """
    errors = []
    _collect_errors(schema, value, "", errors)
    return errors


def _canonicalize(schema, value):
    stype = schema["type"]
    if stype == "object":
        out = {}
        for key, subschema in schema.get("fields", {}).items():
            if key in value:
                out[key] = _canonicalize(subschema, value[key])
        return out
    if stype == "list":
        item_schema = schema.get("item")
        if item_schema is None:
            return list(value)
        return [_canonicalize(item_schema, item) for item in value]
    return value


def serialize(schema, value):
    """Return a canonical dict containing exactly the declared fields.

    Unknown fields are dropped; any validation failure (including unknown
    fields, each reported at its own path) raises ``SchemaValidationError``
    carrying the full ``(path, message)`` list.
    """
    errors = []
    _collect_errors(schema, value, "", errors)
    if errors:
        raise SchemaValidationError(errors)
    return _canonicalize(schema, value)

