"""Compliance tests for valapi.schema."""

import pytest

from valapi import SchemaValidationError, serialize, validate

SCHEMA = {
    "type": "object",
    "fields": {
        "name": {"type": "string", "min_len": 1},
        "age": {"type": "int", "min": 0, "max": 150},
        "tags": {"type": "list", "item": {"type": "string", "pattern": "^[a-z]+$"}},
        "email": {"type": "string"},
        "address": {
            "type": "object",
            "optional": True,
            "fields": {"zip": {"type": "string", "pattern": r"^\d{5}$"}},
        },
    },
}


def paths(errors):
    return {path for path, _ in errors}


# ---------------------------------------------------------------- valid input


def test_valid_document_returns_empty_list():
    doc = {
        "name": "ada",
        "age": 36,
        "tags": ["admin", "dev"],
        "email": "ada@example.com",
        "address": {"zip": "12345"},
    }
    assert validate(SCHEMA, doc) == []


# ------------------------------------------------- all errors, never the first


def test_five_simultaneous_violations_yield_exactly_those_paths():
    doc = {
        "name": 42,  # wrong type at root field
        "age": 200,  # out-of-range int
        "tags": ["ok", "fine", "Bad"],  # pattern miss inside list at index 2
        # 'email' omitted -> missing required field
        "nickname": "ace",  # unknown field
    }
    errors = validate(SCHEMA, doc)
    assert len(errors) == 5
    assert paths(errors) == {"name", "age", "tags[2]", "email", "nickname"}

    # order-insensitive assert on (path, message) pairs too
    assert sorted(errors) == sorted(
        [
            ("name", "expected string, got int"),
            ("age", "200 exceeds maximum 150"),
            ("tags[2]", "does not match pattern '^[a-z]+$'"),
            ("email", "missing required field"),
            ("nickname", "unknown field"),
        ]
    )


def test_multiple_errors_inside_a_single_list():
    doc = {"name": "a", "age": 1, "email": "e", "tags": ["good", "BAD1", "worse!"]}
    assert paths(validate(SCHEMA, doc)) == {"tags[1]", "tags[2]"}


# ------------------------------------------------------- nested-object paths


def test_nested_object_paths_compose():
    doc = {
        "name": "ada",
        "age": 36,
        "email": "x",
        "address": {"zip": "12"},  # pattern miss one level deep
    }
    assert paths(validate(SCHEMA, doc)) == {"address.zip"}


def test_nested_objects_compose_two_levels_deep():
    schema = {
        "type": "object",
        "fields": {
            "address": {
                "type": "object",
                "fields": {
                    "geo": {
                        "type": "object",
                        "fields": {"lat": {"type": "int", "min": -90, "max": 90}},
                    }
                },
            }
        },
    }
    doc = {"address": {"geo": {"lat": 999}}}
    assert paths(validate(schema, doc)) == {"address.geo.lat"}


def test_nested_wrong_typed_container_reports_one_error_at_its_path():
    doc = {"name": "a", "age": 1, "email": "e", "address": ["not", "a", "dict"]}
    assert validate(SCHEMA, doc) == [("address", "expected object, got list")]


# ------------------------------------------------------------ optional fields


def test_optional_field_absent_produces_no_errors():
    doc = {"name": "ada", "age": 36, "email": "x"}  # no 'address'
    assert validate(SCHEMA, doc) == []


def test_optional_field_present_and_valid_produces_no_errors():
    doc = {"name": "ada", "age": 36, "email": "x", "address": {"zip": "00000"}}
    assert validate(SCHEMA, doc) == []


def test_optional_field_wrong_typed_produces_exactly_one_error():
    doc = {"name": "ada", "age": 36, "email": "x", "address": {"zip": 12345}}
    errors = validate(SCHEMA, doc)
    assert len(errors) == 1
    assert errors[0][0] == "address.zip"
    assert errors[0][1] == "expected string, got int"


# ------------------------------------------------------------- type checking


def test_bool_is_not_an_int():
    doc = {"name": "a", "email": "e", "age": True}
    assert paths(validate(SCHEMA, doc)) == {"age"}


def test_non_dict_root_is_reported_at_root_path():
    errors = validate(SCHEMA, [1, 2, 3])
    assert len(errors) == 1
    assert errors[0][0] == ""


def test_unknown_type_in_schema_raises():
    with pytest.raises(ValueError):
        validate({"type": "float8"}, 1.5)


# ----------------------------------------------------------------- serialize


def test_serialize_returns_canonical_dict_with_declared_fields_only():
    doc = {
        "name": "ada",
        "age": 36,
        "email": "x",
        "tags": ["a", "b"],
        "address": {"zip": "12345"},
    }
    assert (
        serialize(SCHEMA, dict(doc, extra="junk"))
        == {
            "name": "ada",
            "age": 36,
            "email": "x",
            "tags": ["a", "b"],
            "address": {"zip": "12345"},
        }
    )
    # field order follows the schema, not the input document
    assert list(serialize(SCHEMA, doc)) == ["name", "age", "tags", "email", "address"]


def test_serialize_rejects_unknown_field_as_error_at_its_path():
    doc = {"name": "a", "age": 1, "email": "e", "nickname": "ace"}
    with pytest.raises(SchemaValidationError) as exc:
        serialize(SCHEMA, doc)
    assert paths(exc.value.errors) == {"nickname"}
    assert exc.value.errors == [("nickname", "unknown field")]


def test_serialize_rejects_any_invalid_document_with_all_errors():
    doc = {"name": 42, "age": -5}
    with pytest.raises(SchemaValidationError) as exc:
        serialize(SCHEMA, doc)
    assert paths(exc.value.errors) == {"name", "age"}

